3	import java.util.regex.Pattern;
4	import net.officefloor.web.ObjectResponse;
5	import org.springframework.web.bind.annotation.RequestBody;
6	
7	/**
8	 * {@code POST /api/clients} — add a client (name + email) and return the created row. Wired by
9	 * {@code officefloor/rest/api/clients.POST.yml}. The create is audited through {@link Audit}.
10	 */
11	public class ClientsPost {
12	
13	    // Every client must carry a proper email. Mirror of the UI check (ClientsPage.isValidEmail) so a
14	    // request that bypasses the form is still rejected before any row or audit record is written.
15	    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
16	
17	    public void service(@RequestBody NewClient body, ClientRepository repository, Audit audit,
18	            ObjectResponse<Client> response) {
19	        String email = body.getEmail() == null ? "" : body.getEmail().trim();
20	        if (!EMAIL.matcher(email).matches()) {
21	            throw new IllegalArgumentException("a client requires a valid email address");
22	        }
23	        Client client = new Client();
24	        client.setName(body.getName());
25	        client.setEmail(body.getEmail());
26	        Client saved = repository.save(client);
27	        audit.record("CLIENT_CREATED id=" + saved.getId() + " name=" + saved.getName());
28	        response.send(saved);
29	    }
30	}
